const raw = $input.first().json;
const text = raw.candidates[0].content.parts[0].text;
const parsed = JSON.parse(text);
const timed = $('Code: Start Researcher Timer').first().json;

return [{
  json: {
    job_id: timed.job_id,
    user_query: timed.user_query,
    results: parsed.results || [],
    latency_ms: Date.now() - timed._start
  }
}];

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'boolean') return String(v);
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return "'" + s.replace(/'/g, "''") + "'";
}

const d = $input.first().json;
const inputCtx = JSON.stringify({ sub_questions: d.results.map(r => r.sub_question) });
const outputData = JSON.stringify({ results: d.results });
const sql = `INSERT INTO agent_outputs (job_id, agent_name, input_context, output_data, model_used, latency_ms) VALUES (${esc(d.job_id)}, 'researcher', ${esc(inputCtx)}::jsonb, ${esc(outputData)}::jsonb, 'gemini-3.6-flash', ${d.latency_ms});`;

return [{ json: { sql } }];

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'boolean') return String(v);
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return "'" + s.replace(/'/g, "''") + "'";
}

const d = $input.first().json;
const jobId = d.job_id;
const rows = [];

for (const r of (d.results || [])) {
  for (const s of (r.sources || [])) {
    const score = (s.relevance_score !== undefined && s.relevance_score !== null) ? Number(s.relevance_score) : 0.5;
    rows.push(`(${esc(jobId)}, ${esc(s.url)}, ${esc(s.title)}, ${esc(s.summary)}, ${score}, 'researcher')`);
  }
}

if (rows.length === 0) {
  return [{ json: { sql: 'SELECT 1;' } }];
}

const sql = `INSERT INTO sources (job_id, url, title, content_summary, relevance_score, agent_source) VALUES ${rows.join(',\n')} ON CONFLICT (job_id, url) DO NOTHING;`;

return [{ json: { sql } }];

const job = $('Postgres: Create Job').first().json;
const researched = $('Code: Parse Researcher Output').first().json.results;
return [{ json: { job_id: job.id, user_query: job.user_query, researched, _start: Date.now() } }];

